ArrayList<Particle> pts;
let onPressed = true;
let showInstruction = false;
let f;

function addSpiral(cx, cy, r, a, iter)
{
	let x, y;
	for (i = 0; i < iter; i++) {
		let t = radians(i);
		x = cx + a * t * r * cos(t) - PI/2;
		y = cy + a * t * r * sin(t) * -1;
		addP(x, y);
  }
}

function addP(x, y)
{
		for (i=0; i<1; i++)
		{
			let newP = new Particle(x, y, i+pts.size(), i+pts.size());
			pts.add(newP);
		}
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  smooth();
  colorMode(HSB);
  rectMode(CENTER);

  pts = new ArrayList<Particle>();

  f = createFont("Calibri", 24, true);

  background(color(0,0,0));

}

let numSpirals = 10;
function draw() {
//   if (showInstruction) drawInstruction();

//   if (onPressed) {
//     for (i=0;i<10;i++) {
//       let newP = new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), i+pts.size(), i+pts.size());
//       pts.add(newP);
//     }
//   }
	while(numSpirals > 0)
	{
		addSpiral(random(0,width), random(0,height), 200, 0.5, 200);
		while(pts.size() > 0)
		{
			for (i=pts.size()-1; i>-1; i--) {
				let p = pts.get(i);
				if (p.dead) {
					pts.remove(i);
				}else{
					p.update();
					p.display();
				}
			}
		}
		numSpirals--;
	}
	noLoop();
}

function drawInstruction(){
  background(255);
  fill(128);
  textAlign(CENTER, CENTER);
  textFont(f);
  textLeading(36);
  text("Drag and draw." + "\n" +
       "Press 'c' to clear the stage." + "\n"
       ,width*0.5, height*0.5);
}

// === Tab: Particle ===
class Particle{
  loc, vel, acc;
  lifeSpan, passedLife;
  dead;
  alpha, weight, weightRange, decay, xOfst, yOfst;
  c;

  constructor(x, y, xOfst, yOfst){
    loc = new PVector(x, y);

    let randDegrees = random(360);
    vel = new PVector(cos(radians(randDegrees)), sin(radians(randDegrees)));
    vel.mult(random(5));

    acc = new PVector(0,0);
    lifeSpan = int(random(30, 90));
    decay = random(0.75, 0.9);
    c = color(255,random(0,0),random(100,125));
    weightRange = random(3,100);

    this.xOfst = xOfst;
    this.yOfst = yOfst;
  }

  function update(){
    if(passedLife>=lifeSpan){
      dead = true;
    }else{
      passedLife++;
    }

		let age = passedLife / lifeSpan;
		let tillDeath = (lifeSpan-passedLife)/lifeSpan;

    alpha = (passedLife / lifeSpan) * 75;
    weight = float(lifeSpan-passedLife)/lifeSpan * weightRange;

    acc.set(0,0);

    let rn = PI/2; //(noise((loc.x+frameCount+xOfst)*.01, (loc.y+frameCount+yOfst)*.01)-.5) *TWO_PI*4;
    let mag = noise((loc.y-frameCount)*.01 + 0.5, (loc.x-frameCount)*.01) + 0.5;
    let dir = new PVector(cos(rn),sin(rn));
    acc.add(dir);
    acc.mult(mag);

    let randRn = random(TWO_PI);
    let randV = new PVector(cos(randRn), sin(randRn));
    randV.mult(.25);
    acc.add(randV);

		c = color(tillDeath * 255 - 40, age * 50 + 100, age * 100 + 100 , 255);

    vel.add(acc);
    vel.mult(decay);
    vel.limit(3);
    loc.add(vel);
  }

  function display(){
    // strokeWeight(weight+1.5);
    // stroke(0, 255);
    // point(loc.x, loc.y);

    strokeWeight(weight);
    stroke(c);
    point(loc.x, loc.y);
  }
}

// === Tab: io ===
function mousePressed() {
  onPressed = true;
  if (showInstruction) {
    background(255);
    showInstruction = false;
  }
}

function mouseReleased() {
  onPressed = false;
}

function keyPressed() {
  if (key == 'c') {
    for (i=pts.size()-1; i>-1; i--) {
      var p = pts.get(i);
      pts.remove(i);
    }
    background(255);
  }
}

